'use strict';

// A host's registrable domain ("site") by the Public Suffix List
// (publicSuffixList.js, generated by `make psl`): idmsa.apple.com →
// apple.com, online.bbva.com.ar → bbva.com.ar, a.uk.com → a.uk.com (uk.com
// is sold by a registry), user.github.io → user.github.io. The standard
// algorithm: the longest matching rule, an exception rule ("!www.ck") over
// a wildcard one ("*.ck"), "*" when nothing matches. An IP address, a host
// that is itself a public suffix, or one with no dot is its own site.
// Background only (importScripts after publicSuffixList.js): 150 KB of
// rules are parsed once, on first use.
const PublicSuffix = (() => {
  let rules = null;
  const load = () => (rules ||= new Set(PUBLIC_SUFFIX_RULES.split(',')));
  const isIp = h => /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || h.includes(':') || h.startsWith('[');

  // How many labels the public suffix of `labels` has.
  function suffixLength(labels) {
    const set = load();
    let best = 1; // the default "*" rule
    for (let i = 0; i < labels.length; i++) {
      const rest = labels.slice(i).join('.');
      if (set.has(`!${rest}`)) return labels.length - i - 1; // an exception wins: its parent is the suffix
      const n = labels.length - i;
      if (n > best && set.has(rest)) best = n;
      if (i > 0 && n + 1 > best && set.has(`*.${rest}`)) best = n + 1;
    }
    return best;
  }

  function registrableDomain(host) {
    const h = String(host || '').toLowerCase().replace(/\.+$/, '');
    if (!h || isIp(h) || !h.includes('.')) return h;
    const labels = h.split('.');
    const n = suffixLength(labels);
    return n >= labels.length ? h : labels.slice(-(n + 1)).join('.');
  }

  return { registrableDomain, updated: PUBLIC_SUFFIX_UPDATED };
})();
